import{_ as e,c as a,o as d,a0 as r}from"./chunks/framework.oTSD2LDJ.js";const b=JSON.parse('{"title":"组件百科","description":"","frontmatter":{"title":"组件百科","editLink":true},"headers":[],"relativePath":"component-encyclopedia/overview.md","filePath":"zh/component-encyclopedia/overview.md"}'),o={name:"component-encyclopedia/overview.md"};function i(n,t,c,l,h,s){return d(),a("div",null,t[0]||(t[0]=[r('<h1 id="组件百科" tabindex="-1">组件百科 <a class="header-anchor" href="#组件百科" aria-label="Permalink to &quot;组件百科&quot;">​</a></h1><p>Uniquenium 的组件分为两类：<strong>主程序内置组件（UDC 开头）</strong> 和 <strong>官方插件组件</strong>。内置组件开箱即用，官方插件组件需额外安装插件包。</p><h2 id="内置组件列表" tabindex="-1">内置组件列表 <a class="header-anchor" href="#内置组件列表" aria-label="Permalink to &quot;内置组件列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>说明</th></tr></thead><tbody><tr><td><a href="./UDCText">UDCText</a></td><td>文本组件，支持 <code>%{}</code> 表达式动态数据</td></tr><tr><td><a href="./UDCImage">UDCImage</a></td><td>图片组件，支持圆角裁剪、按钮动作</td></tr><tr><td><a href="./UDCFrame">UDCFrame</a></td><td>框架容器组件，用于布局划分</td></tr></tbody></table><h2 id="官方插件组件" tabindex="-1">官方插件组件 <a class="header-anchor" href="#官方插件组件" aria-label="Permalink to &quot;官方插件组件&quot;">​</a></h2><p>官方插件包提供更多扩展组件，包括系统监控、天气、日历、媒体播放、便签等。</p><p>详细列表与安装方式请参考 <a href="./../official-plugins">官方插件</a>。</p><h2 id="通用属性" tabindex="-1">通用属性 <a class="header-anchor" href="#通用属性" aria-label="Permalink to &quot;通用属性&quot;">​</a></h2><p>所有 UDC 组件均继承自 <code>UniDeskComBase</code>，拥有以下通用属性：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>visible</code></td><td>bool</td><td>是否可见</td></tr><tr><td><code>width</code></td><td>real</td><td>组件宽度</td></tr><tr><td><code>height</code></td><td>real</td><td>组件高度</td></tr><tr><td><code>x</code></td><td>real</td><td>X 坐标</td></tr><tr><td><code>y</code></td><td>real</td><td>Y 坐标</td></tr><tr><td><code>itemOpacity</code></td><td>real</td><td>不透明度 (0.0 ~ 1.0)</td></tr><tr><td><code>identification</code></td><td>string</td><td>组件唯一 ID</td></tr><tr><td><code>parentIdentification</code></td><td>string</td><td>父组件 ID</td></tr></tbody></table><h2 id="通用方法" tabindex="-1">通用方法 <a class="header-anchor" href="#通用方法" aria-label="Permalink to &quot;通用方法&quot;">​</a></h2><h3 id="propertydataex-→-object" tabindex="-1"><code>propertyDataEx() → object</code> <a class="header-anchor" href="#propertydataex-→-object" aria-label="Permalink to &quot;`propertyDataEx() → object`&quot;">​</a></h3><p>导出组件的自定义属性数据为 JSON 对象（用于保存模板）。</p><h3 id="loadpropertydataex-data" tabindex="-1"><code>loadPropertyDataEx(data)</code> <a class="header-anchor" href="#loadpropertydataex-data" aria-label="Permalink to &quot;`loadPropertyDataEx(data)`&quot;">​</a></h3><p>从 JSON 对象加载自定义属性数据（用于加载模板）。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../controls-reference/overview">控件库概览</a> — UniDesk 控件体系</li><li><a href="./../controls-reference/singletons/UniDeskComManager">UniDeskComManager</a> — 组件管理器</li><li><a href="./../official-plugins">官方插件</a> — 插件组件列表</li></ul>',17)]))}const f=e(o,[["render",i]]);export{b as __pageData,f as default};
